        chk('v89: phiếu cũ: key khớp → đổi sang *, không khớp → giữ key', x[0]['text'] == 'I {*am|is} ok and {a|*an} egg' and 'key' not in x[0] and x[1].get('key') == 'went', x)
        E("commit(w=>{const t=w.tasks.find(x=>x.id==='t13'); t.content.items.forEach(q=>{q.text='<u>He</u> <u>dont</u> like <u>eating</u> fish.'; delete q.opts; delete q.key;}); setQ(t,'Q4');})"); pg.wait_for_timeout(400)
